-- Auto-generated by scripts/curriculum/build-level-sql.mjs -- do not
-- hand-edit the lesson content below; regenerate from the source plan
-- JSON instead if something needs to change.

do $$
declare
  v_course_id uuid := '80f5bd3c-382c-4c5d-9259-a5d035c0c7ec';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
begin
  -- Appending to a level that already exists. Looked up rather than
  -- inserted, so this adds to the learner's current Level 1 instead of
  -- creating a duplicate one, and no existing module is re-parented.
  select id into v_level from public.levels
    where course_id = v_course_id and order_number = 1;

  if v_level is null then
    raise exception 'Level % not found for course % -- refusing to guess', 1, v_course_id;
  end if;

  -- The new modules must sit INSIDE this level, not at the end of the
  -- course. getOrderedLessons() builds the learner's lesson sequence from
  -- modules.order_number alone and ignores level, so a module appended at
  -- the course's max order would put beginner content after the final
  -- level's material. Insert straight after this level's last module and
  -- shift everything below it down instead.
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where level_id = v_level;

  -- Two-phase shift: (course_id, order_number) is unique, and a single
  -- "+ N" update can trip that constraint mid-statement, so park the rows
  -- out of range first and bring them back afterwards.
  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Getting Into the Inbox', 'The existing lessons cover building a list and driving Mailchimp. This one covers the thing that quietly decides whether any of it works: whether your email arrives at all, and whether anyone opens it.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'Why Emails Land in Spam', 'Mailchimp''s own guide to deliverability — what makes a mailbox provider trust you, and what makes it quietly bin your campaign. Under 8 minutes.', 'https://www.youtube.com/watch?v=gkJhobFNnqQ', 1,
      array['Explain what sender reputation is and what damages it', 'Set up permission properly so subscribers actually asked to hear from you', 'Keep a list clean instead of letting it grow stale'],
      'You can write a perfect campaign and have almost nobody see it. Deliverability — whether the message reaches the inbox rather than the spam folder — is decided before anyone reads a word, and it is the part beginners never think about.

PERMISSION IS THE FOUNDATION. Send only to people who asked. A bought list is the fastest way to destroy your sending reputation, because the people on it never wanted your email and mark it as spam; enough of that and the provider starts filtering everything you send, including to the people who did want it. One bad campaign can poison the good ones for months.

SENDER REPUTATION is a score mailbox providers keep on you, built from how recipients behave. Opens and replies help. Spam complaints, bounces to dead addresses and total silence hurt. It is earned slowly and lost quickly.

AUTHENTICATE YOUR DOMAIN. SPF, DKIM and DMARC are DNS records that prove the mail really came from you. Your email platform will walk you through adding them, and it takes about twenty minutes once. Since 2024 Google and Yahoo have required them from anyone sending in bulk — without them, delivery to Gmail addresses is genuinely at risk, and most Kenyan subscribers are on Gmail.

CLEAN THE LIST. Remove hard bounces immediately, and after six months of no opens at all, stop mailing that address. It feels like shrinking your audience. You are removing the dead weight that is dragging down delivery to everyone else.

MAKE UNSUBSCRIBING EASY. A visible one-click unsubscribe is far better than a frustrated reader hitting the spam button, which is what actually harms you.

AND THE LAW APPLIES HERE. Kenya''s Data Protection Act 2019 requires consent before you process someone''s personal data for marketing, and gives them the right to withdraw it. Practically: collect the address with a clear statement of what you will send, keep a record of when and how they signed up, and honour every unsubscribe immediately. The same discipline that keeps you legal is what keeps you out of spam.',
      'Take any list you have, or the one you are starting. Answer three questions in writing: where did each address come from, what did that person agree to receive, and can you prove it? Then check your sending domain has SPF and DKIM set up in your email platform''s settings — most show a plain green or red status. Fix the red one before your next send.',
      '[{"question":"Why is a bought email list so damaging?","options":["Spam complaints from people who never asked wreck delivery for your real subscribers too","The addresses are usually formatted incorrectly","Email platforms charge extra for imported lists","It only slows down the sending speed"],"correct_index":0},{"question":"A subscriber has not opened anything for six months. What is the right move?","options":["Stop mailing that address — inactive contacts drag down delivery for everyone","Increase how often you email them","Move them to a different list and keep sending","Nothing; a larger list is always better"],"correct_index":0}]'::jsonb),
    (v_m1, 'Writing an Email People Actually Open', 'HubSpot on the fundamentals of a marketing email that works — subject lines, structure and a single clear ask. About 6 minutes.', 'https://www.youtube.com/watch?v=94gHaHKmD4Q', 2,
      array['Write a subject line that earns an open without misleading', 'Structure an email around one call to action', 'Design for a phone on a slow connection'],
      'An email gets about two seconds. The subject line decides whether it is opened, the first line decides whether it is read, and one clear ask decides whether anything happens.

SUBJECT LINES: short, specific and honest. "Your order ships Tuesday" beats "Exciting news from our team!" — one tells you something, the other tells you nothing. Curiosity works only if the email delivers on it; a subject that oversells produces an open, then a spam complaint. Avoid ALL CAPS, rows of exclamation marks and the word FREE in caps, all of which filters treat as signals.

THE PREVIEW TEXT — the grey line after the subject in most inboxes — is a second subject line most people leave as "View this email in your browser". Write it deliberately.

ONE CALL TO ACTION. The most common beginner mistake is asking for five things: read the blog, follow us, book a call, buy the thing, reply. A reader given five choices makes none. Decide the single action you want, make that button obvious, and cut the rest.

WRITE TO ONE PERSON. "You", not "our valued customers". Short paragraphs, plain words, the point in the first two lines. Nobody scrolls to find out why you wrote.

SEND FROM A HUMAN NAME. "Grace at Sokoni" gets opened more than "info@", and it makes a reply feel possible — and replies are one of the strongest positive signals to a mailbox provider.

DESIGN FOR A PHONE ON MOBILE DATA. Most Kenyan subscribers will open this on a phone, often on a bundle they are counting. Heavy image-only emails cost them money, load slowly, and break entirely when images are blocked by default — which they often are. Keep real text as text, use images sparingly, and make sure the email still makes sense with none of them loaded. A single tappable button beats a link buried in a paragraph.

AND TEST BEFORE SENDING. Send it to yourself, open it on a phone, and click every link. Broken links in a sent campaign cannot be recalled.',
      'Write one real email: a subject line under 50 characters, deliberate preview text, three short paragraphs and exactly one call to action. Then delete every other ask. Send it to your own phone, read it on mobile data with images off, and time how long it takes to understand what you want the reader to do. If that is over five seconds, cut more.',
      '[{"question":"Why does an email with five calls to action perform badly?","options":["A reader given five choices usually takes none","Email platforms block messages with several links","It always triggers the spam filter","It takes longer to load"],"correct_index":0},{"question":"Why keep an email light on images for a Kenyan audience?","options":["Mobile data costs money, images are often blocked by default, and the email must still make sense without them","Images are not supported on Android","Text-only emails are ranked higher by search engines","Mailchimp charges per image"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'The Right Email to the Right People', 'Sending everything to everyone is what turns a list into an unsubscribe machine. Segmenting, then measuring what happened, is what makes email the highest-return channel there is.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'Segmenting Your List', 'Mailchimp''s own walkthrough of splitting an audience into groups so each person gets email that applies to them. About 9 minutes.', 'https://www.youtube.com/watch?v=1QHqd7Q6gnw', 1,
      array['Split a list by something meaningful rather than mailing everyone', 'Choose the data worth collecting at signup', 'Explain why a smaller, relevant send beats a larger, generic one'],
      'The instinct is to send every email to the whole list, because a bigger number feels better. It is the fastest way to train people to ignore you.

SEGMENTING means sending a message only to the part of the list it applies to. Someone who bought last week does not need the "why not try us" email. Someone in Mombasa does not need the Nairobi event invitation. Relevance is why a list of 300 well-segmented subscribers routinely outperforms 3,000 who all get everything.

SEGMENTS WORTH BUILDING FIRST, in order of usefulness:
- BUYERS versus non-buyers. Completely different messages.
- ENGAGED versus dormant. People who open get more; people who have gone quiet get a re-engagement email or get removed.
- WHAT THEY SIGNED UP FOR, if you offer more than one thing.
- LOCATION, when it changes the offer — delivery areas, event invitations.

COLLECT LITTLE, USE IT. Every extra field on a signup form costs you subscribers, so ask only for what will genuinely change what you send. Email plus first name plus one relevant fact is usually the right trade. Data you never use is just risk you are storing.

A WORD ON TAGS VERSUS FIELDS, since Mailchimp''s naming confuses everyone: a field is a fact about a person that you collected (city, first name); a tag is a label you apply (attended-workshop, vip); a segment is a saved rule that selects people using either. You do not need three copies of your list — one audience, sliced different ways.

PERSONALISATION IS NOT JUST A FIRST NAME. "Hi Grace" in a message that has nothing to do with Grace fools nobody. Sending Grace the thing she actually wants is the personalisation that works — and if a merge tag fails, it prints "Hi ," and looks worse than no name at all, so always set a fallback.',
      'Take your list, or a list you can imagine clearly, and write down three segments you could build today from data you already hold. For each, write the one sentence of email you would send that segment and nobody else. If you cannot write a different sentence for a segment, it is not a useful segment yet — and that tells you what to start collecting at signup.',
      '[{"question":"Why can a list of 300 segmented subscribers beat 3,000 unsegmented ones?","options":["Each person receives email that actually applies to them, so more act and fewer leave","Smaller lists are delivered faster","Email platforms rank small lists more highly","It costs less to send"],"correct_index":0},{"question":"How much information should a signup form ask for?","options":["Only what will change what you send — every extra field loses subscribers","As much as possible, in case it is useful later","Nothing beyond an email address, ever","Whatever the platform''s default form includes"],"correct_index":0}]'::jsonb),
    (v_m2, 'Reading the Numbers After You Send', 'Google''s Digital Marketing programme on collecting and analysing email campaign data — what to measure and what it tells you to change. About 20 minutes, so watch it in two sittings if data is tight.', 'https://www.youtube.com/watch?v=tmVaBsgKMUs', 2,
      array['Interpret open, click and unsubscribe rates without over-reading them', 'Run a fair A/B test on one variable at a time', 'Decide what to change on the next send based on what happened'],
      'Email is the one marketing channel where you can see almost exactly what happened. The trap is reading the wrong number.

THE NUMBERS, and what each actually tells you:

OPEN RATE — how many opened it. This measures your subject line and your sender name, nothing else. IMPORTANT AND OFTEN MISSED: since Apple''s Mail Privacy Protection, opens are automatically registered for many Apple Mail users whether or not a human looked. Open rate is now a rough direction, not a fact. Do not make big decisions on it alone.

CLICK RATE — how many acted. This is the honest number, and the one to optimise. It measures whether the content and the offer were worth anything.

CLICK-TO-OPEN RATE — clicks divided by opens. It separates the two jobs: a good open rate with a poor click-to-open means the subject line wrote a cheque the email did not cash.

UNSUBSCRIBE AND COMPLAINT RATE — the early warning. A rising unsubscribe rate usually means you are sending too often, or to people who never asked. Complaints are more serious; a sustained complaint rate above roughly one in a thousand puts your delivery at risk.

CONVERSIONS — orders, bookings, enquiries. The only number that answers whether it was worth doing.

A/B TEST ONE THING AT A TIME. Change the subject line OR the button OR the send time, never several at once, or you cannot tell which caused the difference. And on a small list, ignore tiny differences: 12% versus 13% on 200 people is noise, not a finding.

BENCHMARK AGAINST YOURSELF. Published industry averages lump wildly different senders together. Your own last five campaigns are the only fair comparison you have.

AND FOR KENYAN SENDERS: much of what email starts finishes in a WhatsApp conversation or a walk-in, where no dashboard follows. Ask new customers where they heard from you and write the answer down. That one habit closes the gap between what the report shows and what actually happened.',
      'Open the report for your most recent campaign — or Mailchimp''s demo data if you have not sent one yet — and write down five numbers: opens, clicks, click-to-open, unsubscribes and any conversions. Then write one sentence naming what you will change on the next send, and the single variable you will test to find out whether it helped. One change, one test.',
      '[{"question":"Why has open rate become unreliable?","options":["Apple Mail Privacy Protection registers opens automatically, whether or not anyone read it","Email platforms stopped tracking opens entirely","Opens are only counted on desktop computers","It is only unreliable on lists under 100 people"],"correct_index":0},{"question":"What makes an A/B test trustworthy?","options":["Changing only one variable, and ignoring tiny differences on small lists","Changing several elements so the winner is clearly better","Sending both versions to the same people","Running it only on your most engaged subscribers"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  -- Bring the shifted modules back, now sitting after the 2 new one(s).
  update public.modules set order_number = order_number - 1000 + 2
   where course_id = v_course_id and order_number > 1000;

end $$;
